public static class ProfileNaming {public static string Name(string id){switch(id){case "general.bat":return "Veyra Base";case "general (ALT2).bat":return "Veyra Alt 1";case "general (ALT3).bat":return "Veyra Alt 2";case "general (ALT4).bat":return "Veyra Alt 3";case "general (ALT5).bat":return "Veyra Alt 4";case "general (ALT6).bat":return "Veyra Alt 5";case "general (ALT7).bat":return "Veyra Alt 6";case "general (ALT8).bat":return "Veyra Alt 7";case "general (ALT9).bat":return "Veyra Alt 8";case "general (ALT10).bat":return "Veyra Alt 9";case "general (ALT11).bat":return "Veyra Alt 10";case "general (ALT12).bat":return "Veyra Alt 11";case "general (ALT13).bat":return "Veyra Alt 12";case "general (ALT).bat":return "Veyra Alt 13";case "general (EXP).bat":return "Veyra Alt 14";case "general (FAKE TLS AUTO ALT).bat":return "Veyra Alt 15";case "general (FAKE TLS AUTO ALT2).bat":return "Veyra Alt 16";case "general (FAKE TLS AUTO ALT3).bat":return "Veyra Alt 17";case "general (FAKE TLS AUTO).bat":return "Veyra Alt 18";case "general (SIMPLE FAKE ALT).bat":return "Veyra Alt 19";case "general (SIMPLE FAKE ALT2).bat":return "Veyra Alt 20";case "general (SIMPLE FAKE).bat":return "Veyra Alt 21";default:return "Veyra Custom";}}}
