public static class Json {
 public static T Read<T>(string path){using(var f=File.OpenRead(path))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(f);}
 public static void Write<T>(string path,T obj){string temp=path+".tmp";using(var f=File.Create(temp))new DataContractJsonSerializer(typeof(T)).WriteObject(f,obj);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
}
public sealed class Engine {
 public readonly string Data;public readonly string Root;public readonly string Bin;public List<Profile> Profiles;public Settings Config;
 readonly object gate=new object();readonly string ownerPath;public Action<string> Logged;
 public Engine(string data){Data=data;Root=Path.Combine(data,"engine-1.10.3");Bin=Path.Combine(Root,"bin","winws.exe");ownerPath=Path.Combine(data,"owner.json");Directory.CreateDirectory(data);Extract();
  Profiles=Directory.GetFiles(Root,"general*.bat").Select(f=>new Profile{Id=Path.GetFileName(f),Name=ProfileNaming.Name(Path.GetFileName(f))}).OrderBy(p=>p.Id=="general.bat"?0:1).ThenBy(p=>Regex.Replace(p.Name,@"\d+",m=>m.Value.PadLeft(4,'0')),StringComparer.OrdinalIgnoreCase).ToList();
  Config=File.Exists(Path.Combine(Data,"settings.json"))?Json.Read<Settings>(Path.Combine(Data,"settings.json")):new Settings();Validate(Config);Seed();
 }
 void Extract(){
  Directory.CreateDirectory(Root);
  using(var resource=Assembly.GetExecutingAssembly().GetManifestResourceStream("engine.zip")){
   if(resource==null)throw new InvalidOperationException("В приложении отсутствует архив движка.");
   using(var zip=new ZipArchive(resource,ZipArchiveMode.Read)){
    foreach(var entry in zip.Entries){if(String.IsNullOrEmpty(entry.Name))continue;int slash=entry.FullName.IndexOf('/');if(slash<0)throw new InvalidDataException("Некорректный архив движка.");string relative=entry.FullName.Substring(slash+1).Replace('/',Path.DirectorySeparatorChar);
     string path=Path.GetFullPath(Path.Combine(Root,relative));if(!path.StartsWith(Path.GetFullPath(Root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Недопустимый путь в архиве.");
     // Lists remain editable. Verify immutable binaries/strategies before elevated execution.
     if(File.Exists(path)){
      bool immutable=relative.StartsWith("bin"+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||relative.EndsWith(".bat",StringComparison.OrdinalIgnoreCase)||relative.EndsWith(".ps1",StringComparison.OrdinalIgnoreCase);
      if(immutable){using(var algorithm=SHA256.Create())using(var embedded=entry.Open())using(var existing=File.OpenRead(path)){string expected=Convert.ToBase64String(algorithm.ComputeHash(embedded));string actual=Convert.ToBase64String(algorithm.ComputeHash(existing));if(expected!=actual)throw new InvalidDataException("Файл движка изменён: "+relative+". Запуск отменён. Сохрани свои списки и переименуй папку engine-1.10.3 в LocalAppData\\ZapretDesk для восстановления при следующем запуске.");}}
      continue;
     }Directory.CreateDirectory(Path.GetDirectoryName(path));
     string tmp=path+".extract";using(var input=entry.Open())using(var output=File.Create(tmp))input.CopyTo(output);File.Move(tmp,path);
    }
   }
  }
 }
 void Seed(){var values=new Dictionary<string,string>{{"ipset-exclude-user.txt","203.0.113.113/32\r\n"},{"list-general-user.txt","# User domains\r\ndomain.example.abc\r\n"},{"list-exclude-user.txt","domain.example.abc\r\n"}};foreach(var kv in values){string path=Path.Combine(Root,"lists",kv.Key);if(!File.Exists(path))File.WriteAllText(path,kv.Value,new UTF8Encoding(false));}string domains=Path.Combine(Root,"lists","list-general-user.txt");string content=File.ReadAllText(domains);var existing=new HashSet<string>(content.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()),StringComparer.OrdinalIgnoreCase);var add=new[]{"telegram.org","desktop.telegram.org","t.me","telegram.me","updates.tdesktop.com","web.telegram.org","kws1.web.telegram.org","kws2.web.telegram.org","kws3.web.telegram.org","kws4.web.telegram.org","kws5.web.telegram.org","kws1-1.web.telegram.org","kws2-1.web.telegram.org","kws3-1.web.telegram.org","kws4-1.web.telegram.org","kws5-1.web.telegram.org","pluto.web.telegram.org","venus.web.telegram.org","aurora.web.telegram.org","vesta.web.telegram.org","flora.web.telegram.org","chatgpt.com","chat.openai.com","openai.com","auth.openai.com","oaistatic.com","oaiusercontent.com"}.Where(x=>!existing.Contains(x)).ToArray();if(add.Length>0)File.AppendAllText(domains,"\r\n# Veyra: official Telegram and ChatGPT domains\r\n"+String.Join("\r\n",add)+"\r\n",new UTF8Encoding(false));}
 public void Validate(Settings c){if(c==null||!Profiles.Any(x=>x.Id==c.Profile))throw new ArgumentException("Неизвестная стратегия.");if(!new[]{"off","tcp","udp","all"}.Contains(c.GameMode))throw new ArgumentException("Неверный режим Game Filter.");foreach(var value in new[]{c.Tcp,c.Udp}){
  if(value==null||value.Length>256||!Regex.IsMatch(value,@"^\d{1,5}(-\d{1,5})?(,\d{1,5}(-\d{1,5})?)*$"))throw new ArgumentException("Порты: например 1024-1934,1936-65535; без пробелов.");
  foreach(var part in value.Split(',')){var n=part.Split('-').Select(int.Parse).ToArray();if(n[0]<1||n[n.Length-1]>65535||n[0]>n[n.Length-1])throw new ArgumentException("Допустимы порты 1–65535 и диапазоны по возрастанию.");}
 }}
 public string Arguments(string profile,Settings c){Validate(c);if(!Profiles.Any(x=>x.Id==profile))throw new ArgumentException("Неизвестный профиль.");string text=File.ReadAllText(Path.Combine(Root,profile),Encoding.UTF8);var m=Regex.Match(text,@"start\s+""zapret:[^\r\n]*?""\s+/min\s+""%BIN%winws\.exe""\s+(.+)$",RegexOptions.Singleline|RegexOptions.IgnoreCase);if(!m.Success)throw new InvalidDataException("Не удалось разобрать стратегию "+profile);
  string args=Regex.Replace(m.Groups[1].Value,@"\^\r?\n\s*"," ").Replace("^!","!").Replace("%BIN%",Path.Combine(Root,"bin")+Path.DirectorySeparatorChar).Replace("%LISTS%",Path.Combine(Root,"lists")+Path.DirectorySeparatorChar).Replace("%GameFilterTCP%",c.GameMode=="all"||c.GameMode=="tcp"?c.Tcp:"12").Replace("%GameFilterUDP%",c.GameMode=="all"||c.GameMode=="udp"?c.Udp:"12").Trim();
  if(Regex.IsMatch(args,@"%[A-Za-z_][A-Za-z_0-9]*%")||args.Contains("\r")||args.Contains("\n"))throw new InvalidDataException("Неподдерживаемая команда стратегии.");if(profile=="general (ALT3).bat"){var quic=Regex.Match(args,@"(?<=\s)--filter-udp=443(?=\s)");if(!quic.Success)throw new InvalidDataException("ALT3: не найден фильтр QUIC.");args=args.Insert(quic.Index+quic.Length," --hostlist=\""+Path.Combine(Root,"lists","list-google.txt")+"\"");}return args;
 }
 public Owner GetOwner(){lock(gate){try{if(!File.Exists(ownerPath))return null;var o=Json.Read<Owner>(ownerPath);using(var p=Process.GetProcessById(o.Pid)){if(!p.HasExited&&p.StartTime.ToUniversalTime().Ticks==o.Ticks&&String.Equals(p.MainModule.FileName,o.Path,StringComparison.OrdinalIgnoreCase)&&String.Equals(o.Path,Bin,StringComparison.OrdinalIgnoreCase))return o;}}catch{}return null;}}
 public bool HasForeign(){var own=GetOwner();foreach(var p in Process.GetProcessesByName("winws")){using(p){if(own==null||p.Id!=own.Pid)return true;}}return false;}
 public void Start(string profile,Settings c){lock(gate){foreach(var process in Process.GetProcessesByName("winws")){process.Dispose();throw new InvalidOperationException("winws уже запущен. Остановите другую копию или службу zapret её собственными средствами.");}
  string args=Arguments(profile,c);var info=new ProcessStartInfo(Bin,args){WorkingDirectory=Path.GetDirectoryName(Bin),UseShellExecute=false,CreateNoWindow=true};
  using(var p=Process.Start(info)){try{Json.Write(ownerPath,new Owner{Pid=p.Id,Ticks=p.StartTime.ToUniversalTime().Ticks,Path=Bin,Profile=profile});if(p.WaitForExit(900))throw new InvalidOperationException("winws завершился, код "+p.ExitCode+". Возможен конфликт драйвера WinDivert или сетевых фильтров.");}catch{try{if(!p.HasExited)p.Kill();}catch{}throw;}}
  Log("Запущена стратегия: "+profile);if(profile=="general (ALT3).bat")Log("ALT3: list-google.txt добавлен в первое правило UDP/443 для YouTube QUIC.");
 }}
 public void Stop(){lock(gate){var o=GetOwner();if(o!=null){try{using(var p=Process.GetProcessById(o.Pid)){// Revalidate directly before stopping; never use taskkill by image name.
  if(p.StartTime.ToUniversalTime().Ticks==o.Ticks&&String.Equals(p.MainModule.FileName,o.Path,StringComparison.OrdinalIgnoreCase)){p.Kill();if(!p.WaitForExit(4000))throw new IOException("Процесс не завершился вовремя.");}}}catch(ArgumentException){} }
  if(File.Exists(ownerPath))File.Delete(ownerPath);
 }}
 public void Save(Settings value){Validate(value);if(GetOwner()!=null)throw new InvalidOperationException("Отключитесь перед изменением настроек.");Json.Write(Path.Combine(Data,"settings.json"),value);Config=value.Copy();Log("Настройки сохранены.");}
 public void Log(string text){string line="["+DateTime.Now.ToString("HH:mm:ss")+"] "+text;try{lock(gate){File.AppendAllText(Path.Combine(Data,"app.log"),line+Environment.NewLine,new UTF8Encoding(false));}}catch{}var handler=Logged;if(handler!=null)handler(line);}
 public string[] Logs(){try{return File.Exists(Path.Combine(Data,"app.log"))?File.ReadAllLines(Path.Combine(Data,"app.log"),Encoding.UTF8).Reverse().Take(100).Reverse().ToArray():new string[0];}catch{return new string[0];}}
 public static Result Recommend(IEnumerable<Result> results){return results.Where(x=>x.Error==null&&x.Passed>0).OrderByDescending(x=>x.Passed).ThenBy(x=>x.Ms).FirstOrDefault();}
 public static async Task<List<Check>> ProbeTelegramWeb(CancellationToken cancel){var list=new List<Check>();string[] urls={"https://telegram.org/","https://desktop.telegram.org/"};for(int i=0;i<urls.Length;i++){cancel.ThrowIfCancellationRequested();var row=new Check{Name=i==0?"Telegram.org":"Скачать Telegram"};var clock=Stopwatch.StartNew();try{using(var handler=new HttpClientHandler{AllowAutoRedirect=true,AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate})using(var client=new HttpClient(handler)){client.Timeout=TimeSpan.FromSeconds(7);client.DefaultRequestHeaders.UserAgent.ParseAdd("Mozilla/6.0 Veyra");using(var response=await client.GetAsync(urls[i],HttpCompletionOption.ResponseHeadersRead,cancel).ConfigureAwait(false)){row.Code=(int)response.StatusCode;row.Ok=row.Code>=200&&row.Code<400;}}}catch(OperationCanceledException){cancel.ThrowIfCancellationRequested();row.Error="Таймаут";}catch(Exception){row.Error="Нет HTTPS-ответа";}clock.Stop();row.Ms=clock.ElapsedMilliseconds;list.Add(row);}return list;}
 public static async Task<List<Check>> Probe(CancellationToken cancel){var list=new List<Check>();string[] names={"YouTube","Discord","Discord API","Google","GitHub","ChatGPT"};string[] urls={"https://www.youtube.com/","https://discord.com/","https://discord.com/api/v10/gateway","https://www.google.com/generate_204","https://github.com/","https://chatgpt.com/"};
  for(int i=0;i<urls.Length;i++){cancel.ThrowIfCancellationRequested();var row=new Check{Name=names[i]};var watch=Stopwatch.StartNew();try{
    using(var handler=new HttpClientHandler{AllowAutoRedirect=true,AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate})using(var client=new HttpClient(handler)){client.Timeout=TimeSpan.FromSeconds(5);client.DefaultRequestHeaders.UserAgent.ParseAdd("Mozilla/5.0 Veyra/1.1-beta.2");client.DefaultRequestHeaders.ConnectionClose=true;using(var response=await client.GetAsync(urls[i],HttpCompletionOption.ResponseHeadersRead,cancel).ConfigureAwait(false)){row.Code=(int)response.StatusCode;row.Ok=row.Code>=200&&row.Code<400;}}
   }catch(OperationCanceledException){cancel.ThrowIfCancellationRequested();row.Error="Таймаут";}catch(Exception e){row.Error=e.Message;}watch.Stop();row.Ms=watch.ElapsedMilliseconds;list.Add(row);
  }return list;
 }
