 public void Normalize(){if(!Themes.Ids.Contains(Theme))Theme="amber";if(!new[]{"off","space","constellation","aurora","graphite","amber"}.Contains(Background))Background="off";if(!new[]{"dark","light","system"}.Contains(Mode))Mode="dark";if(Nav!="left"&&Nav!="top")Nav="left";if(!System.Text.RegularExpressions.Regex.IsMatch(Accent??"","^#[0-9a-fA-F]{6}$"))Accent="";Name=(Name??"").Substring(0,Math.Min(24,(Name??"").Length));Hello=(Hello??"").Substring(0,Math.Min(60,(Hello??"").Length));Subtitle=(Subtitle??"").Substring(0,Math.Min(120,(Subtitle??"").Length));if(Shape!="circle"&&Shape!="square")Shape="round";if(Design!="orbit2"){Design="orbit2";}Motion=false;if(Background=="constellation")Background="amber";Name="";Avatar="";}

}
