public static class Palette {
 public const string Bg="#18120E",Top="#211810",Card="#281E17",Card2="#31241B",Border="#614B38",Text="#F5EBE0",Muted="#C4B3A3",Accent="#FF9D52",AccentDark="#332012",Green="#9BDAA7",Red="#F3AEA2";
 public static string Blend(string baseColor,string accent,double strength){var result="#";for(int n=0;n<3;n++){int a=Convert.ToByte(baseColor.Substring(n*2+1,2),16),b=Convert.ToByte(accent.Substring(n*2+1,2),16);result+=((int)Math.Round(a*(1-strength)+b*strength)).ToString("X2");}return result;}
 public static string Map(string c,string theme){var parts=(theme??"graphite:dark:").Split(':');int i=Array.IndexOf(Themes.Ids,parts[0]);if(i<0)i=1;bool light=parts.Length>1&&(parts[1]=="light"||parts[1]=="system"&&SystemLight());string accent=parts.Length>2&&parts[2].Length==7?parts[2]:light?Themes.LightAccents[i]:Themes.Accents[i];
 switch(c){case Bg:return Blend(light?"#F4F5F7":"#14171D",accent,light?.08:.12);case Top:return Blend(light?"#FFFFFF":"#1B2028",accent,light?.06:.16);case Card:return Blend(light?"#FFFFFF":"#202630",accent,light?.08:.17);case Card2:return Blend(light?"#EFF1F5":"#282F3A",accent,light?.08:.19);case Border:return Blend(light?"#D5D9E1":"#3D4656",accent,light?.15:.25);case Text:return light?"#232833":"#F0F3F9";case Muted:return light?"#566171":"#B8C2D0";case Green:return light?"#236544":"#8BD5AA";case Red:return light?"#A63737":"#F5A19A";case Accent:return accent;case AccentDark:return Contrast(accent);case "#362619":case "#473020":case "#3A2A1E":case "#4A3322":return Blend(light?"#E6EAF1":"#2B3443",accent,light?.16:.28);case "#AD7748":case "#B57948":case "#9C7B5D":return accent;case "#71503A":case "#523C2B":return Blend(light?"#CBD3DE":"#3C4658",accent,.18);}return c;}
 public static double Luminance(string hex){double l=0;double[] weights={.2126,.7152,.0722};for(int i=0;i<3;i++){double c=Convert.ToByte(hex.Substring(1+i*2,2),16)/255.0;l+=weights[i]*(c<=.04045?c/12.92:Math.Pow((c+.055)/1.055,2.4));}return l;}
 public static string Contrast(string hex){double l=Luminance(hex),dark=Luminance("#171B19");double a=(l+.05)/(dark+.05),b=1.05/(l+.05);return Math.Max(a,b)<4.5?"#000000":a>=b?"#171B19":"#FFFFFF";}
 public static bool SystemLight(){try{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")){object value=key==null?null:key.GetValue("AppsUseLightTheme");if(value!=null)return Convert.ToInt32(value)!=0;}}catch{}return true;}
 public static Color C(string s){return ColorTranslator.FromHtml(s);}
}
public static class UiLayout {
 public static float Sidebar(Appearance look,float width){return look.Nav=="left"&&width>=900?(look.SidebarCollapsed?64:200):0;}
 public static int Columns(float w){return w>=1400?6:w>=520?3:2;}
 public static float Header(float w){return w>=1400?76:70+(float)Math.Ceiling(6f/Columns(w))*44+14;}
 public static float Content(float w){return Math.Min(1120,w-(w<700?32:64));}
}
public static class Scenes {
 sealed class Builder {
  public Scene S=new Scene();public List<Op> Ops;public float Offset;public bool Fixed;public string Layer="body";
  public Builder(){Ops=S.Body;}
  public void Rect(float x,float y,float w,float h,string color,string border=null,float radius=12,string kind="rect",string id=null){Ops.Add(new Op{Kind=kind,Id=id,X=x,Y=y+Offset,W=w,H=h,Color=color,Stroke=border,Radius=radius});}
  public void Text(string text,float x,float y,float w,float h,float size=14,string color=Palette.Text,bool bold=false,string align="left"){Ops.Add(new Op{Kind="text",Text=text??"",X=x,Y=y+Offset,W=w,H=h,Size=size,Color=color,Bold=bold,Align=align});}
  public void Group(string text,string icon,float x,float y,float w,float h,float size=14,string color=Palette.Text,bool bold=false,string id=null){Ops.Add(new Op{Kind="group",Text=text,Icon=icon,Id=id,X=x,Y=y+Offset,W=w,H=h,Size=size,Color=color,Bold=bold,Align="center"});}
  public void Icon(string name,float x,float y,float size=20,string color=Palette.Muted,string id=null){Ops.Add(new Op{Kind="icon",Text=name,Id=id,X=x,Y=y+Offset,W=size,H=size,Color=color});}
  public void Hit(string id,float x,float y,float w,float h,bool enabled=true){S.Hits.Add(new Hit{Id=id,Rect=new Rect(x,y+Offset,w,h),Enabled=enabled,Fixed=Fixed,Layer=Layer});}
