public sealed class SkyDot {public float X,Y,Radius,Alpha;}
public sealed class SkyLink {public float X1,Y1,X2,Y2;}
public sealed class SkyMap {public List<SkyDot> Dots=new List<SkyDot>();public List<SkyLink> Links=new List<SkyLink>();}
public static class BackdropGeometry {
 public static SkyMap Make(float width,float height,bool amber){var map=new SkyMap();var r=new Random(2709);float w=width+144,h=height+144;int loose=Math.Max(25,Math.Min(120,(int)(w*h/(amber?35000:11000))));for(int i=0;i<loose;i++)map.Dots.Add(new SkyDot{X=(float)r.NextDouble()*w,Y=(float)r.NextDouble()*h,Radius=amber?1.25f:.65f+(float)r.NextDouble()*.7f,Alpha=.3f+(float)r.NextDouble()*.5f});
 if(amber){int groups=Math.Max(4,Math.Min(14,(int)(w*h/110000)));for(int i=0;i<groups;i++){float cx=54+(float)r.NextDouble()*(w-108),cy=54+(float)r.NextDouble()*(h-108);int n=3+r.Next(2);var points=new List<SkyDot>();for(int j=0;j<n;j++){double angle=j*Math.PI*2/n+r.NextDouble()*.45;float radius=18+(float)r.NextDouble()*27;var p=new SkyDot{X=cx+(float)Math.Cos(angle)*radius,Y=cy+(float)Math.Sin(angle)*radius,Radius=1.45f,Alpha=.65f};points.Add(p);map.Dots.Add(p);}for(int j=0;j<n-1;j++)map.Links.Add(new SkyLink{X1=points[j].X,Y1=points[j].Y,X2=points[j+1].X,Y2=points[j+1].Y});if(i%2==0)map.Links.Add(new SkyLink{X1=points[n-1].X,Y1=points[n-1].Y,X2=points[0].X,Y2=points[0].Y});}}
 return map;}
}
public static class MotionMath {public static float Ease(float t){t=Math.Max(0,Math.Min(1,t));return 1-(float)Math.Pow(1-t,3);}public static float Approach(float value,float target){return Math.Abs(value-target)<.008f?target:value+(target-value)*.25f;}}
