public sealed class ClickGate {readonly long delay;long last=long.MinValue;public ClickGate(int milliseconds){delay=(long)(milliseconds*(double)Stopwatch.Frequency/1000);}public bool Enter(){return EnterAt(Stopwatch.GetTimestamp());}public bool EnterAt(long now){if(last!=long.MinValue&&now-last<delay)return false;last=now;return true;}}

