 void PositionInputs(){if(IsDisposed||view.Current==null)return;float scale=DeviceDpi/96f;bool visible=tab=="settings"&&picker=="";Rect[] rects={view.Current.TcpRect,view.Current.UdpRect};TextBox[] boxes={tcp,udp};for(int i=0;i<2;i++){var source=rects[i];var r=source==null?null:new Rect(source.X,source.Y-view.Scroll,source.W,source.H);boxes[i].Visible=visible&&r!=null&&r.Y>=view.EffectiveHeaderHeight+4&&r.Y+r.H<view.ClientSize.Height/scale&&(toast==""||r.Y+r.H<view.ClientSize.Height/scale-104);if(r!=null){boxes[i].SetBounds((int)(r.X*scale),(int)(r.Y*scale),(int)(r.W*scale),(int)(r.H*scale));float size=14*scale;if(Math.Abs(boxes[i].Font.Size-size)>.2f){boxes[i].Font=new Font("Segoe UI",size,FontStyle.Regular,GraphicsUnit.Pixel);}}if(boxes[i].Visible)boxes[i].BringToFront();boxes[i].Enabled=!busy&&owner==null;boxes[i].BackColor=Palette.C(Palette.Map(Palette.Bg,look.Colors));boxes[i].ForeColor=Palette.C(Palette.Map(Palette.Text,look.Colors));}}
 void Toast(string value,bool error=false){toast=value.Length>190?value.Substring(0,187)+"…":value;toastUntil=DateTime.UtcNow.AddSeconds(error?10:5);view.RefreshScene();}
 void Error(Exception ex){engine.Log(ex.Message);Toast(ex.Message,true);}
 void Navigate(string id){if(!Navigation.Known(id)||tab==id)return;picker="";view.BeginTransition();scrolls[tab]=view.Scroll;tab=id;if(tab=="settings"&&!dirty){draft=engine.Config.Copy();SetInputs();}view.Scroll=scrolls.ContainsKey(tab)?scrolls[tab]:0;view.Current=null;tcp.Visible=false;udp.Visible=false;view.Invalidate();}
 async void ClickAction(string id){if(closing)return;try{if(id.StartsWith("category:")){category=id.Substring(9);view.RefreshScene();return;}
 if(id=="fullscreen:toggle"){if(fullscreenClicks.Enter())ToggleFullscreen();return;}if(id=="fullscreen:exit"){if(fullscreen)ToggleFullscreen();return;}if(id=="tg:toggle"){if(tgBusy)return;tgBusy=true;view.RefreshScene();try{if(telegram!=null&&telegram.Running){telegram.Dispose();telegram=null;}else{telegram=new TelegramBridge(TelegramBridge.LoadKey(engine.Data),null,text=>TelegramDiagnostics.Write(engine.Data,text));telegram.StartSaved(engine.Data);Toast("Теперь нажми «Добавить в Telegram» и включи прокси в Telegram.");}}finally{tgBusy=false;view.RefreshScene();}return;}if(id=="tg:open"){if(telegram!=null&&telegram.Running)Process.Start(new ProcessStartInfo(telegram.Link){UseShellExecute=true});return;}
 if(id=="download:site"||id=="download:github"){Process.Start(new ProcessStartInfo(id=="download:site"?"https://desktop.telegram.org/":"https://github.com/telegramdesktop/tdesktop/releases/latest"){UseShellExecute=true});return;}
 if(id=="author:github"){Process.Start(new ProcessStartInfo("https://github.com/nosmokee"){UseShellExecute=true});return;}if(id=="header:settings"){Navigate("settings");return;}if(id=="sidebar:toggle"){look.SidebarCollapsed=!look.SidebarCollapsed;SaveLook();return;}if(id.StartsWith("layout:")){look.Nav=id.Substring(7);SaveLook();return;}if(id.StartsWith("mode:")){look.Mode=id.Substring(5);SaveLook();return;}if(id.StartsWith("shape:")){look.Shape=id.Substring(6);SaveLook();return;}
 if(id.StartsWith("edit:")){string field=id.Substring(5);string val=field=="name"?look.Name:field=="hello"?look.Hello:look.Subtitle;string answer=EditText(field=="name"?"Ник панели":field=="hello"?"Заголовок на главной":"Подзаголовок на главной",val,field=="name"?24:field=="hello"?60:120);if(answer!=null){if(field=="name")look.Name=answer;else if(field=="hello")look.Hello=answer;else look.Subtitle=answer;SaveLook();}return;}
 if(id=="accent:reset"){look.Accent="";SaveLook();return;}if(id=="accent"){using(var d=new ColorDialog{FullOpen=true,Color=Palette.C(Palette.Map(Palette.Accent,look.Colors))})if(d.ShowDialog(this)==DialogResult.OK){look.Accent="#"+d.Color.R.ToString("X2")+d.Color.G.ToString("X2")+d.Color.B.ToString("X2");SaveLook();}return;}
 if(id.StartsWith("picker:")){PickerAction(id);return;}if(id.StartsWith("theme:")){look.SelectTheme(id.Substring(6));SaveLook();return;}if(id.StartsWith("background:")){look.Background=id.Substring(11);look.Motion=false;SaveLook();return;}if(id.StartsWith("nav:")){Navigate(id.Substring(4));return;}if(id=="connect"){await Toggle();return;}if(id=="probe"){await Probe();return;}if(id=="scan"||id=="scan:quick"){await Scan();return;}if(id=="cancel"){if(cancellation!=null){cancelRequested=true;cancellation.Cancel();status="Останавливаем проверку…";view.Invalidate();}return;}if(id=="best"){if(best!=null)Apply(best.Profile);return;}if(id.StartsWith("choose:")){var p=engine.Profiles.FirstOrDefault(z=>z.Id==id.Substring(7));if(p!=null)Apply(p);return;}if(id=="save"){Save();return;}if(id=="profile"||id=="game"){ShowPicker(id);return;}if(id=="welcome"){Navigate("about");return;}if(id=="folder")Process.Start(new ProcessStartInfo("explorer.exe","\""+engine.Data+"\""){UseShellExecute=true});}catch(Exception ex){Error(ex);}}

 string EditText(string title,string value,int max){using(var form=new Form{Text=title,ClientSize=new Size(480,170),StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog,Font=new Font("Segoe UI",11)}){var label=new Label{Text=title,Left=20,Top=16,Width=440,Height=30};var input=new TextBox{Text=value,MaxLength=max,Left=20,Top=54,Width=440};var ok=new Button{Text="Сохранить",Left=210,Top=110,Width=120,Height=38,DialogResult=DialogResult.OK};var cancel=new Button{Text="Отмена",Left=340,Top=110,Width=120,Height=38,DialogResult=DialogResult.Cancel};form.Controls.AddRange(new Control[]{label,input,ok,cancel});form.AcceptButton=ok;form.CancelButton=cancel;return form.ShowDialog(this)==DialogResult.OK?input.Text.Trim():null;}}
 void SaveLook(){look.Normalize();try{Json.Write(Path.Combine(engine.Data,"appearance.json"),look);}catch(Exception ex){Error(ex);}PositionInputs();view.Invalidate();}
 void ShowPicker(string id){if(busy||owner!=null||view.Current==null)return;picker=id;pickerOptions=id=="profile"?engine.Profiles.Select(p=>p.Name).ToArray():new[]{"Выключен","TCP + UDP","Только TCP","Только UDP"};pickerIndex=id=="profile"?engine.Profiles.FindIndex(p=>p.Id==draft.Profile):Array.IndexOf(new[]{"off","all","tcp","udp"},draft.GameMode);pickerIndex=Math.Max(0,pickerIndex);pickerStart=Math.Max(0,pickerIndex-2);tcp.Visible=false;udp.Visible=false;view.Focus();view.Invalidate();}
 void PickerAction(string id){if(id=="picker:close"){picker="";view.Invalidate();return;}if(picker=="")return;if(id.StartsWith("picker:wheel:")){pickerStart=Math.Max(0,Math.Min(pickerOptions.Length-1,pickerStart+(id.EndsWith("up")?-2:2)));view.Invalidate();return;}if(id.StartsWith("picker:key:")){pickerIndex=Math.Max(0,Math.Min(pickerOptions.Length-1,pickerIndex+(id.EndsWith("up")?-1:1)));pickerStart=Math.Max(0,pickerIndex-2);view.Invalidate();return;}int index;if(id=="picker:apply")index=pickerIndex;else if(!Int32.TryParse(id.Substring(7),out index))return;if(index<0||index>=pickerOptions.Length)return;if(picker=="profile")draft.Profile=engine.Profiles[index].Id;else draft.GameMode=new[]{"off","all","tcp","udp"}[index];dirty=true;picker="";view.Invalidate();}
  async Task Toggle(){if(busy||foreign)return;busy=true;status="Изменение подключения…";RefreshState();operation=Task.Run(()=>{if(engine.GetOwner()!=null){engine.Stop();engine.Log("Zapret отключён.");}else engine.Start(engine.Config.Profile,engine.Config.Copy());});try{await operation;checks.Clear();}catch(Exception ex){Error(ex);}finally{busy=false;operation=null;status="Готово";RefreshState();}}
 async Task Probe(){if(busy)return;busy=true;cancelRequested=false;cancellation=new CancellationTokenSource();status="Проверяем 6 адресов…";RefreshState();operation=RunProbe(cancellation.Token);try{await operation;}catch(OperationCanceledException){Toast("Проверка остановлена.");}catch(Exception ex){Error(ex);}finally{EndOperation();}}
 async Task RunProbe(CancellationToken token){checks=await Engine.Probe(token);engine.Log("HTTPS: "+String.Join("; ",checks.Select(c=>c.Name+" "+(c.Ok?"OK":"нет"))));Toast("Проверка завершена: "+checks.Count(c=>c.Ok)+" / 6.");}
 async Task Scan(){if(busy||owner!=null||foreign)return;busy=true;cancelRequested=false;scanFinished=false;scanCancelled=false;best=null;results.Clear();baseline.Clear();checks.Clear();summary="";status="Исходная проверка сети…";cancellation=new CancellationTokenSource();RefreshState();var config=engine.Config.Copy();operation=RunScan(config,cancellation.Token);try{await operation;}catch(OperationCanceledException){scanCancelled=true;best=null;summary="Проверка остановлена. Ниже — частичные результаты, без рекомендации.";engine.Log("Автоподбор отменён.");}catch(Exception ex){best=null;summary="Проверка не завершена: "+ex.Message;Error(ex);}finally{try{await Task.Run(()=>engine.Stop());}catch(Exception ex){Error(ex);}EndOperation();}}
 async Task RunScan(Settings config,CancellationToken token){if(await Task.Run(()=>engine.GetOwner()!=null||engine.HasForeign()))throw new InvalidOperationException("Сначала отключите другие копии zapret.");engine.Log("Начата проверка 22 стратегий по 6 адресам.");baseline=await Engine.Probe(token);view.Invalidate();foreach(var profile in engine.Profiles){token.ThrowIfCancellationRequested();status=profile.Name+"  ·  "+results.Count+" / "+engine.Profiles.Count;view.Invalidate();var row=new Result{Profile=profile};try{await Task.Run(()=>engine.Start(profile.Id,config),token);await Task.Delay(600,token);row.Checks=await Engine.Probe(token);if(await Task.Run(()=>engine.GetOwner()==null))throw new InvalidOperationException("winws завершился во время проверки.");}catch(OperationCanceledException){throw;}catch(Exception ex){row.Error=ex.Message;engine.Log(profile.Name+": "+ex.Message);}finally{await Task.Run(()=>engine.Stop());}results.Add(row);view.Invalidate();}
  token.ThrowIfCancellationRequested();best=Engine.Recommend(results);scanFinished=true;summary=best==null?"Ни одна стратегия не прошла HTTPS-проверки.":"Проверка завершена.";status="Готово  ·  "+results.Count+" / "+engine.Profiles.Count;engine.Log(best==null?"Проверка завершена без рекомендации.":"Лучшая стратегия: "+best.Profile.Name+" ("+best.Passed+"/6)");try{var report=new StringBuilder();report.AppendLine(DateTime.Now.ToString("s"));report.AppendLine("HTTPS reachability only; NOT video, voice or Telegram test.");report.AppendLine("Baseline HTTPS: "+String.Join("; ",baseline.Select(c=>c.Name+"="+(c.Ok?"OK":"FAIL")+" code="+c.Code+" ms="+c.Ms)));report.AppendLine("Profile\tPassed\tTotal ms\tError");foreach(var r in results)report.AppendLine(r.Profile.Id+"\t"+r.Passed+"/6\t"+r.Ms+"\t"+r.Error);report.AppendLine(best==null?"No recommendation":"Best: "+best.Profile.Id);File.WriteAllText(Path.Combine(engine.Data,"last-test.txt"),report.ToString(),Encoding.UTF8);}catch(Exception ex){engine.Log("Не удалось сохранить отчёт: "+ex.Message);}view.SetScroll(0);
 }
 void EndOperation(){busy=false;operation=null;if(cancellation!=null){cancellation.Dispose();cancellation=null;}cancelRequested=false;if(!scanFinished)status="Готово";RefreshState();}
 void Apply(Profile p){if(busy||owner!=null)return;try{var c=engine.Config.Copy();c.Profile=p.Id;engine.Save(c);draft=c.Copy();dirty=false;SetInputs();Toast("Выбрана стратегия "+p.Name+". Можно подключаться.");RefreshState();}catch(Exception ex){Error(ex);}}
 void Save(){if(busy||owner!=null)return;try{draft.Tcp=tcp.Text.Trim();draft.Udp=udp.Text.Trim();var old=engine.Config.Copy();engine.Save(draft.Copy());if(old.GameMode!=draft.GameMode||old.Tcp!=draft.Tcp||old.Udp!=draft.Udp){results.Clear();baseline.Clear();best=null;scanFinished=false;summary="Параметры фильтра изменены. Выполните проверку заново.";}checks.Clear();dirty=false;Toast("Настройки сохранены.");RefreshState();}catch(Exception ex){Error(ex);}}
 void Export(){using(var dialog=new SaveFileDialog{FileName="zapret-desk-log.txt",Filter="Текстовый файл|*.txt"})if(dialog.ShowDialog(this)==DialogResult.OK)File.WriteAllLines(dialog.FileName,engine.Logs(),Encoding.UTF8);}
 void OnLog(string line){if(IsDisposed)return;if(InvokeRequired){try{BeginInvoke(new Action<string>(OnLog),line);}catch{}return;}logCache=logCache.Concat(new[]{line}).Reverse().Take(100).Reverse().ToArray();view.Invalidate();}
 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==Keys.F11){if((msg.LParam.ToInt64()&(1L<<30))==0&&fullscreenClicks.Enter())ToggleFullscreen();return true;}if(keyData==Keys.Escape&&fullscreen&&picker==""){ToggleFullscreen();return true;}return base.ProcessCmdKey(ref msg,keyData);}
 void ToggleFullscreen(){if(closing)return;windowMode.Toggle(this);view.RefreshScene();PositionInputs();}
 public void RestoreWindow(){if(closing)return;Show();view.PauseVisuals(false);if(WindowState==FormWindowState.Minimized){WindowState=fullscreen?FormWindowState.Normal:FormWindowState.Maximized;if(fullscreen)Bounds=Screen.FromHandle(Handle).Bounds;}Activate();Native.SetForegroundWindow(Handle);}
 void OnClosing(object sender,FormClosingEventArgs e){if(permitClose)return;if(e.CloseReason==CloseReason.WindowsShutDown||e.CloseReason==CloseReason.TaskManagerClosing){if(cancellation!=null)cancellation.Cancel();if(telegram!=null)telegram.Dispose();try{engine.Stop();}catch{}tray.Visible=false;return;}e.Cancel=true;if(Lifetime.HideOnClose(e.CloseReason==CloseReason.UserClosing,permitClose)){BeginInvoke(new Action(HideToTray));}else {var ignored=ExitApp();}}
 void HideToTray(){if(closing||IsDisposed)return;view.PauseVisuals(true);Hide();Native.HideWindow(Handle);}
 async Task ExitApp(){if(closing)return;closing=true;if(telegram!=null)telegram.Dispose();timer.Stop();if(cancellation!=null)cancellation.Cancel();Enabled=false;try{if(operation!=null)await operation;}catch{}try{await Task.Run(()=>engine.Stop());engine.Log("Выход из приложения; собственный winws остановлен.");}catch(Exception ex){try{File.AppendAllText(Path.Combine(engine.Data,"app.log"),"Ошибка остановки: "+ex.Message+Environment.NewLine);}catch{}}permitClose=true;tray.Visible=false;Close();}
 protected override void WndProc(ref Message m){if(m.Msg==Native.ShowMessage){RestoreWindow();return;}base.WndProc(ref m);}
 protected override void Dispose(bool disposing){if(disposing){if(telegram!=null)telegram.Dispose();timer.Dispose();tray.Visible=false;tray.Dispose();engine.Logged-=OnLog;}base.Dispose(disposing);}
}
public static class Lifetime {public static bool HideOnClose(bool userClose,bool exiting){return userClose&&!exiting;}}
