public sealed class WelcomeForm:Form {
 readonly SceneView view=new SceneView();bool accepted;string page="welcome";readonly string data;
 readonly WindowFullscreen windowMode=new WindowFullscreen();readonly ClickGate fullscreenClicks=new ClickGate(250);
 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==Keys.F11){if((msg.LParam.ToInt64()&(1L<<30))==0&&fullscreenClicks.Enter()){windowMode.Toggle(this);view.RefreshScene();}return true;}if(keyData==Keys.Escape&&windowMode.Active){windowMode.Toggle(this);view.RefreshScene();return true;}return base.ProcessCmdKey(ref msg,keyData);}
 public WelcomeForm(string path,bool priorAccepted=false){data=path;accepted=priorAccepted;MinimizeBox=false;Text=Native.WindowTitle;Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.None;StartPosition=FormStartPosition.CenterScreen;MinimumSize=new Size(390,420);ClientSize=new Size(620,720);try{Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);}catch{}view.Dock=DockStyle.Fill;view.GetModel=()=>new Model{Tab=page,Consent=accepted,Onboarding=true,Look=new Appearance{Background="off",Motion=false}};view.Action=id=>{if(id=="fullscreen:toggle"){if(fullscreenClicks.Enter()){windowMode.Toggle(this);view.RefreshScene();}return;}if(id=="fullscreen:exit"){if(windowMode.Active){windowMode.Toggle(this);view.RefreshScene();}return;}if(id=="policy"||id=="nav:about"){page="about";view.Scroll=0;view.RefreshScene();return;}if(id=="nav:home"||id=="back"){page="welcome";view.Scroll=0;view.RefreshScene();return;}if(id=="consent"){accepted=!accepted;view.RefreshScene();}else if(id=="start"&&accepted){try{Directory.CreateDirectory(data);Json.Write(Path.Combine(data,"consent.json"),new ConsentRecord{PolicyVersion=ConsentRecord.Current,AcceptedUtc=DateTime.UtcNow.ToString("o")});DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,"Не удалось сохранить согласие: "+ex.Message,"Сохранение",MessageBoxButtons.OK,MessageBoxIcon.Error);}}};Controls.Add(view);Shown+=(s,e)=>{float scale=DeviceDpi/96f;var a=Screen.FromControl(this).WorkingArea;MinimumSize=new Size(Math.Min(a.Width,(int)(390*scale)),Math.Min(a.Height,(int)(420*scale)));Size=new Size(Math.Min(a.Width,(int)(640*scale)),Math.Min(a.Height,(int)(780*scale)));Location=new Point(a.Left+(a.Width-Width)/2,a.Top+(a.Height-Height)/2);Native.DarkTitle(Handle);};}
 public static bool EnsureAccepted(string data){bool prior=false;try{var r=Json.Read<ConsentRecord>(Path.Combine(data,"consent.json"));prior=r!=null&&r.PolicyVersion==ConsentRecord.Current&&!String.IsNullOrWhiteSpace(r.AcceptedUtc);}catch{}using(var form=new WelcomeForm(data,prior))return form.ShowDialog()==DialogResult.OK;}

 public static void ShowPolicy(IWin32Window owner,string data){using(var form=new WelcomeForm(data))form.ShowDialog(owner);}
}

internal static class Program {
 static bool Admin(){return new System.Security.Principal.WindowsPrincipal(System.Security.Principal.WindowsIdentity.GetCurrent()).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(Native.RestoreExisting())return;
  // Check before elevation: reopening an already running/tray instance does not
  // require a second UAC prompt. Only the first real instance is elevated.
  if(!Admin()){bool first;using(var launching=new Mutex(true,"Local\\ZapretDesk.Launch.v3",out first)){if(!first)return;try{var info=new ProcessStartInfo(Application.ExecutablePath,"--elevated"){UseShellExecute=true,Verb="runas",WorkingDirectory=Path.GetDirectoryName(Application.ExecutablePath)};using(var child=Process.Start(info)){for(int i=0;i<200;i++){if(child.HasExited||Native.FindWindow(null,Native.WindowTitle)!=IntPtr.Zero)break;Thread.Sleep(100);}}}catch(System.ComponentModel.Win32Exception){}finally{launching.ReleaseMutex();}}return;}
  bool created;using(var mutex=new Mutex(true,"Local\\ZapretDeskNative-v2",out created)){if(!created){Native.RestoreExisting();return;}try{string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ZapretDesk");if(!WelcomeForm.EnsureAccepted(data))return;ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var engine=new Engine(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ZapretDesk"));Application.Run(new MainForm(engine));}catch(Exception error){ShowStartupError(error);}finally{mutex.ReleaseMutex();}}
 }
 static void ShowStartupError(Exception error){try{string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ZapretDesk");Directory.CreateDirectory(dir);File.AppendAllText(Path.Combine(dir,"startup-error.log"),DateTime.Now.ToString("s")+" "+error+Environment.NewLine);}catch{}
  using(var window=new Form{Text="Veyra — ошибка запуска",BackColor=Palette.C(Palette.Bg),ForeColor=Palette.C(Palette.Text),ClientSize=new Size(680,290),StartPosition=FormStartPosition.CenterScreen}){window.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,HideSelection=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=window.BackColor,ForeColor=window.ForeColor,Font=new Font("Segoe UI",11),Text="Не удалось запустить приложение.\r\n\r\n"+error.Message+"\r\n\r\nПодробности — в LocalAppData\\ZapretDesk\\startup-error.log. Не отключайте защиту Windows."});Application.Run(window);}
 }
